'use strict';
let QUESTION_INDEX=new Map(),SEARCH_INDEX=new Map(),poolCache=null;
let BANK=[],PAPERS=[],DATA={},tab='home',mode='mc',session=null,config={from:106,to:115,count:20,weights:{'行政法概要':30,'行政學概要':30,'法學知識與英文':20,'國文':10,'政治學概要':10}},page=0;
const $=s=>document.querySelector(s),e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),subjs=['行政法概要','行政學概要','法學知識與英文','國文','政治學概要'];
function load(){try{DATA=JSON.parse(localStorage.getItem('adminDaily.v1')||'{}')}catch{DATA={}}DATA.records??={};DATA.notes??={};DATA.noteUpdated??={};DATA.errorMeta??={};DATA.drafts??={};DATA.custom??=[];DATA.history??=[];if(DATA.config)config=DATA.config;try{session=JSON.parse(localStorage.getItem('adminDaily.session')||'null')}catch{} }
function save(){try{DATA.config=config;localStorage.setItem('adminDaily.v1',JSON.stringify(DATA));localStorage.setItem('adminDaily.session',JSON.stringify(session))}catch{toast('儲存失敗，請先匯出備份並確認瀏覽器空間。')}}
function toast(msg){$('#toast').textContent=msg;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,4000)}
function pool(){const key=mode+'|'+config.from+'|'+config.to;if(poolCache?.bank===BANK&&poolCache.key===key)return poolCache.value;const value=BANK.filter(q=>q.type===mode&&q.year>=config.from&&q.year<=config.to);poolCache={bank:BANK,key,value};return value}
function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function weightedSample(all,n,weights){const groups={};for(const q of all){if((weights[q.subject]||0)>0)(groups[q.subject]??=[]).push(q)};for(const k of Object.keys(groups))groups[k]=shuffle(groups[k]);n=Math.min(n,Object.values(groups).reduce((s,g)=>s+g.length,0));const counts={};for(let i=0;i<n;i++){const active=Object.keys(groups).filter(k=>groups[k].length>(counts[k]||0));const sum=active.reduce((s,k)=>s+weights[k],0);let best=active[0],diff=-Infinity;for(const k of active){const d=(i+1)*weights[k]/sum-(counts[k]||0);if(d>diff){best=k;diff=d}}counts[best]=(counts[best]||0)+1}return shuffle(Object.entries(counts).flatMap(([k,n])=>groups[k].slice(0,n)))}
function navIcon(name){const paths={
 pencil:'<path d="m15 5 4 4M4 15l12-12a2.8 2.8 0 0 1 4 4L8 19l-5 2 1-6Z"/>',
 book:'<path d="M6 3h12a2 2 0 0 1 2 2v16H6a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2Z"/><path d="M4 18a2 2 0 0 1 2-2h14"/>',
 retry:'<path d="M3 12a9 9 0 1 0 3-6.7L3 8"/><path d="M3 3v5h5"/>',
 trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>',
 notebook:'<rect x="5" y="3" width="15" height="18" rx="2"/><path d="M3 7h4M3 12h4M3 17h4M10 8h6M10 12h6M10 16h4"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5h5"/>',
 settings:'<path d="M12.00 4.70L13.76 3.17L15.44 3.69L16.06 5.93L17.16 6.84L19.48 7.00L20.31 8.56L19.16 10.58L19.30 12.00L20.83 13.76L20.31 15.44L18.07 16.06L17.16 17.16L17.00 19.48L15.44 20.31L13.42 19.16L12.00 19.30L10.24 20.83L8.56 20.31L7.94 18.07L6.84 17.16L4.52 17.00L3.69 15.44L4.84 13.42L4.70 12.00L3.17 10.24L3.69 8.56L5.93 7.94L6.84 6.84L7.00 4.52L8.56 3.69L10.58 4.84Z"/><circle cx="12" cy="12" r="3"/>'
};return '<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+paths[name]+'</svg>'}
function nav(){const items=[['home',navIcon('pencil'),'今日練習'],['wrong',navIcon('retry'),'錯題演練'],['bank',navIcon('book'),'歷年題庫'],['notes',navIcon('notebook'),'我的筆記'],['records',navIcon('clock'),'學習紀錄'],['settings',navIcon('settings'),'題庫與備份']];$('#nav').innerHTML=items.map(([id,icon,name])=>`<button data-tab="${id}" class="${tab===id?'active':''}"><span>${icon}</span>${name}</button>`).join('');$('#crumb').textContent=items.find(x=>x[0]===tab)?.[2]||'練習中'}
function goto(t){tab=t;page=0;render();window.scrollTo(0,0)}
function applyCurrentSyllabus(){
 BANK=BANK.filter(q=>subjs.includes(q.subject));
 QUESTION_INDEX=new Map(BANK.map(q=>[q.id,q]));SEARCH_INDEX=new Map(BANK.map(q=>[q.id,formatExamText(q.text)+' '+(q.options||[]).map(o=>formatExamText(o)).join(' ')]));poolCache=null;
 PAPERS=PAPERS.filter(p=>subjs.some(k=>p.subject===k||p.subject.startsWith(k+'（')));
 config.weights=Object.fromEntries(subjs.map(k=>[k,config.weights?.[k]??10]));
 if(session){const active=new Set(BANK.map(q=>q.id)),before=session.ids.slice(0,session.index).filter(id=>active.has(id)).length;session.ids=session.ids.filter(id=>active.has(id));if(!session.ids.length)session=null;else{session.index=Math.min(before,session.ids.length-1);session.answers=Object.fromEntries(Object.entries(session.answers||{}).filter(([id])=>active.has(id)))}}
}
function learningTotals(){const totals={attempts:0,right:0,wrong:0,subjects:Object.fromEntries(subjs.map(k=>[k,{attempts:0,right:0}]))};for(const [id,r] of Object.entries(DATA.records)){const q=QUESTION_INDEX.get(id);if(!q)continue;const a=Number(r.attempts)||0,b=Number(r.right)||0;totals.attempts+=a;totals.right+=b;totals.wrong+=r.wrong?1:0;totals.subjects[q.subject].attempts+=a;totals.subjects[q.subject].right+=b}return totals}
function stats(totals=learningTotals()){const {attempts,right,wrong}=totals;return `<div class="stats"><div class="stat"><span class="muted">累積練習</span><b>${attempts}<small>題</small></b></div><div class="stat"><span class="muted">整體正確率</span><b>${attempts?Math.round(right/attempts*100):'—'}<small>${attempts?'%':'尚未作答'}</small></b></div><div class="stat"><span class="muted">待複習錯題</span><b>${wrong}<small>題</small></b></div><div class="stat"><span class="muted">已收錄考題</span><b>${BANK.length.toLocaleString()}<small>題</small></b></div></div>`}
function intro(title,desc,show=false){if(!show)return '';return `<div class="intro"><div><div class="eyebrow">PERSONAL STUDY SPACE</div><h1>${title}</h1><p class="muted">${desc}</p></div><span class="pill">普考 · 一般行政</span></div>`}
function modeTabs(){return `<div class="tabs"><button data-mode="mc" aria-pressed="${mode==='mc'}" class="${mode==='mc'?'active':''}">選擇題練習</button><button data-mode="essay" aria-pressed="${mode==='essay'}" class="${mode==='essay'?'active':''}">申論與作文</button></div>`}
function weightsUI(){let p=pool(),counts={};for(const q of p)counts[q.subject]=(counts[q.subject]||0)+1;let total=subjs.reduce((s,k)=>s+(counts[k]?config.weights[k]||0:0),0);return subjs.map(k=>{let num=counts[k]||0,w=config.weights[k]||0,pct=total?Math.round(w/total*100):0;return `<div class="weight"><label for="w-${subjs.indexOf(k)}">${e(k)} <span class="fine">${num} 題</span></label><div class="bar"><i style="width:${pct}%"></i></div><input id="w-${subjs.indexOf(k)}" type="number" min="0" max="100" value="${w}" data-weight="${e(k)}" ${num?'':'disabled'} aria-label="${e(k)}比例權重"><span class="fine">${num?pct:0}%</span></div>`}).join('')}
const DAILY_QUOTES=[{"zh":"能帶給你內心平靜的，只有你自己。","en":"Nothing can bring you peace but yourself.","author":"愛默生","work":"《自立》","source":"https://www.gutenberg.org/cache/epub/16643/pg16643-images.html"},{"zh":"學而時習之，不亦說乎？","author":"孔子","work":"《論語・學而》","source":"https://ctext.org/analects/xue-er/zh"},{"zh":"堅持做自己，別一味模仿他人。","en":"Insist on yourself; never imitate.","author":"愛默生","work":"《自立》","source":"https://www.gutenberg.org/cache/epub/16643/pg16643-images.html"},{"zh":"溫故而知新，可以為師矣。","author":"孔子","work":"《論語・為政》","source":"https://tct.gov.taipei/News_Content.aspx?n=F1FEADA96EEB06A9&s=BB684B0293DBF4F0"},{"zh":"簡化，再簡化。","en":"Simplify, simplify.","author":"梭羅","work":"《湖濱散記》","source":"https://www.gutenberg.org/files/205/205-h/205-h.htm"},{"zh":"學而不思則罔，思而不學則殆。","author":"孔子","work":"《論語・為政》","source":"https://tct.gov.taipei/News_Content.aspx?n=F1FEADA96EEB06A9&s=BB684B0293DBF4F0"},{"zh":"最重要的是，忠於你自己。","en":"This above all: to thine own self be true;","author":"莎士比亞","work":"《哈姆雷特》","source":"https://www.gutenberg.org/files/1524/1524-h/1524-h.htm"},{"zh":"知之為知之，不知為不知，是知也。","author":"孔子","work":"《論語・為政》","source":"https://tct.gov.taipei/News_Content.aspx?n=F1FEADA96EEB06A9&s=BB684B0293DBF4F0"},{"zh":"棲守道德者，寂寞一時；依附權勢者，淒涼萬古。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"道千乘之國，敬事而信，節用而愛人，使民以時。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"有無相生，難易相成，長短相形，高下相盈，音聲相和，前後相隨。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"涉世淺，點染亦淺；歷事深，機械亦深。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"弟子入則孝，出則弟，謹而信，汎愛眾，而親仁。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"是以聖人處無為之事，行不言之教；萬物作而弗始，生而弗有，為而弗恃，功成而不居。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"君子之心事，天青日白，不可使人不知。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"君子不重則不威，學則不固。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"挫其銳，解其紛，和其光，同其塵。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"勢利紛華，不近者為潔，近之而不染者為尤潔；智械機巧，不知者為高，知之而不用者為尤高。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"君子食無求飽，居無求安，敏於事而愼於言，就有道而正焉：可謂好學也已。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"虛而不屈，動而愈出。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"耳中常聞逆耳之言，心中常有拂心之事，纔是進德修行的砥石。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"不患人之不己知，患不知人也。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"多聞數窮，不如守中。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"疾風怒雨，禽鳥戚戚；霽日光風，草木欣欣。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"為政以德，譬如北辰，居其所，而眾星共之。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"天地所以能長且久者，以其不自生，故能長生。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"醲肥辛甘非真味，真味只是淡；神奇卓異非至人，至人只是常。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"詩三百，一言以蔽之，曰思無邪。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"是以聖人後其身而身先，外其身而身存。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"天地寂然不動，而氣機無一息少停；日月晝夜奔馳，而貞明則萬古不易。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"道之以政，齊之以刑，民免而無恥；道之以德，齊之以禮，有恥且格。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"上善若水，水善利萬物而不爭。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"夜深人靜，獨坐觀心，始覺妄窮而真獨露，每於此中得大機趣；既覺真現而妄難逃，又於此中得大慚忸。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"吾十有五而志於學；三十而立；四十而不惑；五十而知天命；六十而耳順；七十而從心所欲，不踰矩。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"居善地，心善淵，與善仁，言善信，正善治，事善能，動善時。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"恩裏由來生害，故快意時，須早回頭；敗後或反成功，故拂心處，莫便放手。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"視其所以，觀其所由，察其所安，人焉廋哉！","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"持而盈之，不如其已。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"面前的田地要放得寬，使人無不平之歎；身後的惠澤要流得長，使人有不匱之思。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"君子周而不比，小人比而不周。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"揣而銳之，不可長保。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"徑路窄處，留一步與人行；滋味濃的，減三分讓人嗜。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"人而無信，不知其可也。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"金玉滿堂，莫之能守。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"作人無甚高遠事業，擺脫得俗情，便入名流；為學無甚增益工夫，減除得物累，便超聖境。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"射不主皮，為力不同科，古之道也。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"富貴而驕，自遺其咎。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"交友須帶三分俠氣，做人要存一點素心。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"居上不寬，為禮不敬，臨喪不哀，吾何以觀之哉！","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"生之，畜之，生而不有，為而不恃，長而不宰。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"寵利毋居人前，德業毋落人後；受享毋踰分外，修為毋減分中。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"不仁者，不可以久處約，不可以長處樂。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"三十輻共一轂，當其無，有車之用。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"處世讓一步為高，退步即進步的張本；待人寬一分是福，利人實利己的根基。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"惟仁者能好人，能惡人。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"埏埴以為器，當其無，有器之用。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"蓋世功勞，當不得一個矜字；彌天罪過，當不得一個悔字。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"苟志於仁矣，無惡也。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"鑿戶牖以為室，當其無，有室之用。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"完名美節，不宜獨任，分些與人，可以遠害全身；辱行污名，不宜全推，引些歸己，可以韜光養德。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"富與貴，是人之所欲也，不以其道得之，不處也。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"故有之以為利，無之以為用。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"若業必求滿，功必求盈者，不生內變，必召外憂。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"士志於道，而恥惡衣惡食者，未足與議也！","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"執古之道，以御今之有。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"攻人之惡，毋太嚴，要思其堪受；教人之善，毋過高，當使其可從。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"君子之於天下也，無適也，無莫也，義之與比。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"致虛，極；守靜，篤。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"居軒冕之中，不可無山林的氣味；處林泉之下，須要懷廊廟的經綸。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"君子懷德，小人懷土；君子懷刑，小人懷惠。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"萬物並作，吾以觀復。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"處世不必邀功，無過便是功；與人不求感德，無怨便是德。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"不患無位，患所以立。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"夫物芸芸，各復歸其根。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"憂勤是美德，太苦則無以適性怡情；澹泊是高風，太枯則無以濟人利物。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"君子喻於義，小人喻於利。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"歸根曰靜，靜曰覆命。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"人至事窮勢蹙，宜原其初心；士當行滿功成，要觀其末路。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"見賢思齊焉，見不賢而內自省也。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"覆命曰常，知常曰明。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"居卑而後知登高之為危，處晦而後知向明之太露；守靜而後知好動之過勞，養默而後知多言之為躁。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"古者言之不出，恥躬之不逮也。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"知常容，容乃公，公乃王，王乃天，天乃道，道乃久，歿身不殆。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"待小人，不難於嚴，而難於不惡；待君子，不難於恭，而難於有禮。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"君子欲訥於言而敏於行。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"信不足焉，有不信焉。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"寧守渾噩而黜聰明，留些正氣還天地；寧謝紛華而甘澹泊，遺個清名在乾坤。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"晏平仲善與人交，久而敬之。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"故令有所屬：見素抱樸，少思寡慾，絕學無憂。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"降魔者，先降自心，心伏，則群魔退聽；馭橫者，先馭此氣，氣平，則外橫不侵。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"伯夷，叔齊，不念舊惡，怨是用希。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"曲則全，枉則直，窪則盈，敝則新，少則得，多則惑。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"慾路上事，毋樂其便而姑為染指，一染指便深入萬仞；理路上事，無憚其難而稍為退步，一退步便遠隔千山。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"巧言，令色，足恭，左丘明恥之，丘亦恥之。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"不自見，故明；不自是，故彰；不自伐，故有功；不自矜，故長。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"念頭濃者，自待厚，待人亦厚，處處皆濃；念頭淡者，自待薄，待人亦薄，處處皆淡。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"吾未見能見其過，而內自訟者也。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"夫唯不爭，故天下莫能與之爭。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"風恬浪靜中，見人生之真境；味淡聲希處，識心體之本然。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"十室之邑，必有忠信如丘者焉，不如丘之好學也。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"故飄風不終朝，驟雨不終日。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"立身不高一步立，如塵裏振衣，泥中濯足，如何超達；處世不退一步處，如飛蛾投燭，羝羊觸藩，如何安樂。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"質勝文則野，文勝質則史。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"企者不立；跨者不行；自見者不明；自是者不彰；自伐者無功；自矜者不長。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"學者要收拾精神，併歸一路。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"人之生也直，罔之生也幸而免。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"寂兮寥兮，獨立而不改，周行而不殆，可以為天地母。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"進德修道，要個木石的念頭，若一有欣羨，便趨慾境；濟世經邦，要段雲水的趣味，若一有貪著，便墮危機。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"知之者，不如好之者，好之者，不如樂之者。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"故道大，天大，地大，人亦大。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"福莫福於少事，禍莫禍於多心。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"知者樂水，仁者樂山。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"人法地，地法天，天法道，道法自然。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"處治世宜方，處亂世宜圓，處叔季之世，當方圓並用；待善人宜寬，待惡人宜嚴，待庸眾之人，當寬嚴互存。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"君子博學於文，約之以禮，亦可以弗畔矣夫！","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"重為輕根，靜為躁君。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"我有功於人不可念，而過則不可不念；人有恩於我不可忘，而怨則不可不忘。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"中庸之為德也，其至矣乎！","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"輕則失根，躁則失君。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"施恩者，內不見己，外不見人，則斗粟可當萬鍾之惠；利物者，計己之施，責人之報，雖百鎰難成一文之功。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"述而不作，信而好古，竊比於我老彭。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"善行，無轍跡；善言，無瑕謫；善數，不用籌策；善閉，無關楗而不可開；善結，無繩約而不可解。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"心地清淨，方可讀書學古。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"默而識之，學而不厭，誨人不倦，何有於我哉？","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"是以聖人常善救人，故無棄人；常善救物，故無棄物。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"奢者富而不足，何如儉者貧而有餘；能者勞而府怨，何如拙者逸而全真。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"德之不脩，學之不講，聞義不能徙，不善不能改，是吾憂也。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"故善人者，不善人之師；不善人者，善人之資。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"讀書不見聖賢，為鉛槧傭；居官不愛子民，為衣冠盜；講學不尚躬行，為口頭禪；立業不思種德，為眼前花。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"自行束脩以上，吾未嘗無誨焉。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"知其雄，守其雌，為天下谿。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"苦心中，常得悅心之趣；得意時，須防失意之悲。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"不憤不啟；不悱不發。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"知其白，守其黑，為天下式。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"春至時和，花尚舖一段好色，鳥且囀幾句好音。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"富而可求也，雖執鞭之士，吾亦為之；如不可求，從吾所好。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"知其榮，守其辱，為天下谷。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"學者有段競業的心思，又要有段瀟灑的趣味。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"飯疏食，飮水，曲肱而枕之，樂亦在其中矣。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"是以聖人無為，故無敗；無執，故無失。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"真廉無廉名，圖名者正所以為貪；大巧無巧術，用術者乃所以為拙。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"我非生而知之者，好古，敏以求之者也。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"是以聖人去甚，去奢，去泰。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"人知名位為樂，不知無名無位之樂為最真；人知飢寒為憂，那知不飢不寒之憂為更甚。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"三人行，必有我師焉。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"果而勿矜，果而勿伐，果而勿驕。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"為惡而畏人知，惡中猶有善路；為善而急人知，善處即是惡根。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"蓋有不知而作之者，我無是也。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"果而不得已，果而勿強。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"十語九中，未必稱奇，一語不中，則愆尤駢集；十謀九成，未必歸功，一謀不成，則訾議叢興。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"文，莫吾猶人也；躬行君子，則吾未之有得！","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"始制有名，名亦既有，夫亦將知止，知止可以不殆。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"天理路上甚寬，稍游心，胸中便覺高明廣大；人慾路上甚窄，纔寄跡，眼前俱是荊棘泥塗。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"奢則不孫，儉則固；與其不孫也，甯固。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"知人者智，自知者明。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"一苦一樂相磨鍊，鍊極而成福者，其福始久；一疑一信相參勘，勘極而成知者，其知始真。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"君子坦蕩蕩，小人長戚戚。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"勝人者有力，自勝者強。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"心不可不虛，虛則義理來居；心不可不實，實則物慾不入。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"恭而無禮則勞，愼而無禮則葸，勇而無禮則亂，直而無禮則絞。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"萬物恃之以生而不辭，功成而不有。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"人只一會貪私，便銷剛為柔，塞智為昏，變恩為慘，染潔為污，壞了一生人品。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"興於詩，立於禮，成於樂。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"以其終不自為大，故能成其大。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"圖未就之功，不如保已成之業；悔既往之失，不如防將來之非。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"如有周公之才之美，使驕且吝，其餘不足觀也已！","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"是以大丈夫處其厚，不居其薄；處其實，不居其華。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"氣象要高曠，而不可疏狂；心思要縝密，而不可瑣屑；趣味要沖澹，而不可偏枯；操守要嚴明，而不可激烈。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"篤信好學，守死善道。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"故貴以賤為本，高以下為基。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"風來疏竹，風過而竹不留聲；雁度寒潭，雁去而潭不留影。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"不在其位，不謀其政。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"反者道之動；弱者道之用。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"清能有容，仁能善斷；明不傷察，直不過矯。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"學如不及，猶恐失之。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"天下萬物生於有，有生於無。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"閒中不放過，忙處有受用；靜中不落空，動處有受用；暗中不欺隱，明處有受用。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"吾未見好德如好色者也。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"上士聞道，勤而行之；中士聞道，若存若亡；下士聞道，大笑之。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"靜中念慮澄澈，見心之真體；閒中氣象從容，識心之真機；淡中意趣沖夷，得心之真味。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"譬如為山，未成一簣，止，吾止也！","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"道生一，一生二，二生三，三生萬物。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"靜中靜非真靜，動處靜得來，纔是性天之真境；樂纔樂非真樂，苦中樂得來，纔見心體之真機。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"後生可畏，焉知來者之不如今也？","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"萬物負陰而抱陽，沖氣以為和。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"天薄我以福，吾厚吾德以迓之；天勞我以形，吾逸吾心以補之；天阨我以遇，吾亨吾道以通之。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"主忠信，毋友不如己者，過則勿憚改。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"故物或損之而益，或益之而損。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"平民肯種德施惠，便是無位的公相；士夫徒貪權市寵，竟成有爵的乞人。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"三軍可奪帥也，匹夫不可奪志也。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"天下之至柔，馳騁天下之至堅。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"家人有過，不宜暴怒，不宜輕棄。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"歲寒，然後知松柏之後凋也。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"不言之教，無為之益，天下希及之。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"此心常看得圓滿，天下自無缺憾之世界；此心常放得寬平，天下自無險側之人情。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"知者不惑，仁者不憂，勇者不懼。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"甚愛必大費；多藏必厚亡。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"居逆境中，周身皆鍼砭藥石，砥節勵行而不覺；處順境內，滿前盡兵刃戈矛，銷膏糜骨而不知。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"可與共學，未可與適道；可與適道，未可與立；可與立，未可與權。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"故知足不辱，知止不殆，可以長久。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"文章做到極處，無有他奇，只是恰好；人品做到極處，無有他異，只是本然。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"聽訟，吾猶人也；必也使無訟乎！","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"大成若缺，其用不弊。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"不責人小過，不發人陰私，不念人舊惡。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"博學以文，約之以禮；亦可以弗畔矣夫！","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"大盈若沖，其用不窮。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"士君子持身不可輕，輕則物能撓我，而無悠閑鎮定之趣；用意不可重，重則我為物泥，而無瀟灑活潑之機。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"君子成人之美，不成人之惡。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"大直若屈，大巧若拙，大辯若訥。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"天地有萬古，此身不再得；人生只百年，此日最易過。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"其身正，不令而行；其身不正，雖令不從。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"禍莫大於不知足；咎莫大於欲得。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"市私恩，不如扶公議；結新知，不如敦舊好；立榮名，不如種隱德；尚奇節，不如謹庸行。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"苟正其身矣，於從政乎何有？","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"故知足之足，常足矣。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"曲意而使人喜，不若直躬而使人忌；無善而致人譽，不若無惡而致人毀。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"不得中行而與之，必也狂狷乎：狂者進取，狷者有所不為也。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"為學日益，為道日損。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"處父兄骨肉之變，宜從容，不宜激烈；遇朋友交遊之失，宜剴切，不宜優游。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"君子和而不同，小人同而不和。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"損之又損，以至於無為。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"小處不滲漏，暗處不欺隱，末路不怠荒，纔是個真正英雄。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"君子易事而難說也；說之不以道，不說也；及其使人也，器之。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"聖人常無心，以百姓心為心。","author":"老子","work":"《道德經》","source":"https://zh.wikisource.org/zh-hant/老子_(匯校版)","excerpt":true},{"zh":"千金難結一時之歡，一飯竟致終身之感。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"君子泰而不驕；小人驕而不泰。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"衰颯的景象，就在盛滿中；發生的機緘，即在零落內。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"士而懷居，不足以為士矣！","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"毋以己之長而形人之短，毋因己之拙而忌人之能。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"邦有道，危言危行；邦無道，危行言孫。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"念頭昏散處，要知提醒；念頭喫緊時，要知放下。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"有德者必有言，有言者不必有德。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"霽日青天，倏變為迅雷震電；疾風怒雨，倏轉為朗月晴空。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"貧而無怨，難；富而無驕，易。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"覺人之詐，不形於言；受人之侮，不動於色。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"其言之不怍，則為之也難！","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"毋因群疑而阻獨見，毋任己意而廢人言，毋私小惠而傷大體，毋借公論以快私情。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"君子上達，小人下達。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"青天白日的節義，自暗室屋漏中培來；旋乾轉坤的經綸，自臨深履薄處繅出。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"古之學者為己，今之學者為人。","author":"孔子","work":"《論語》","source":"https://zh.wikisource.org/zh-hant/論語/全覽","excerpt":true},{"zh":"德者才之主，才者德之奴。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"士君子，貧不能濟物者，遇人癡迷處，出一言提醒之；遇人急難處，出一言解救之，亦是無量功德。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"德隨量進，量由識長。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"反己者，觸事皆成藥石；尤人者，動念即是戈矛。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"事業文章隨身銷毀，而精神萬古如新；功名富貴逐世轉移，而氣節千載一日。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"作人無點真懇念頭，便成個花子，事事皆虛；涉世無段圓活機趣，便是個木人，處處有礙。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"水不波則自定，鑑不翳則自明，故心無可清，去其混之者，而清自現；樂不必尋，去其苦之者，而樂自存。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"事有急之不白者，寬之或自明，毋躁急以速其忿；人有操之不從者，縱之或自化，毋操切以益其頑。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"謝事當謝於正盛之時，居身宜居於獨後之地。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"交市人，不如友山翁；謁朱門，不如親白屋；聽街談巷語，不如聞牧唱樵歌；談今人失德過差，不如述古人嘉言懿行。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"德者事業之基，未有基不固而棟宇堅久者。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"信人者，人未必盡誠，己則獨誠矣；疑人者，人未必皆詐，己則先詐矣。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"念頭寬厚的，如春風煦育，萬物遭之而生；念頭忌刻的，如朔雪陰凝，萬物遭之而死。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"為善不見其益，如草裏東瓜，自應暗長；為惡不見其損，如庭前春雪，勢必潛消。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"遇故舊之交，意氣要愈新；處隱微之地，心跡宜愈顯；待衰朽的輩，恩禮當愈隆。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"勤者敏於德義，而世人借勤以濟其貧；儉者淡於貨利，而世人假儉以飾其吝。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"憑意興作為者，隨作則隨止，豈是不退之車輪；從情識解悟者，有悟則有迷，終非常明之燈燭。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"人之過誤宜恕，而在己則不可恕；己之困辱宜忍，而在人則不可忍。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"能脫俗便是奇，作意尚奇者，不為奇而為異；不合污便是清，矯情求清者，不為清而為激。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"心虛則性現，不息心而求見性，如撥波覓月；意淨則心清，不了意而求明心，如索鏡增塵。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"無事時，心易昏昧，宜寂寂而照以惺惺；有事時，心易奔逸，宜惺惺以而主以寂寂。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"議事者，身在事外，宜悉利害之情；任事者，身居事中，當絕利害之慮。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"一念慈祥，可以醞釀兩間和氣；寸心潔白，可以昭垂百代清芬。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"忙裏要偷閑，須先向閑時討個把柄；鬧中要取靜，須先從靜裏立個根基；不然，未有不因境而遷，隨時而靡者。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"不昧己心，不盡人情，不竭物力；三者可以為天地立心，為生民立命，為子孫造福。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"處富貴之地，要知貧賤的痛癢；當少壯之時，須念衰老的辛酸。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"磨礪當如百煉之金，急就者，必非邃養；施為宜似千鈞之弩，輕發者，決無宏功。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"山之高峻處無木，而谿谷迴環則草木叢生；水之湍急處無魚，而淵潭停蓄則魚鼈聚集。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"建功立業者，多圓融之士；僨事失機者，必執拗之人。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"處世不必與俗同，亦不宜與俗異；作事不必令人喜，亦不可令人憎。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"日既暮而猶煙霞絢爛，歲將晚而更橙橘芳馨。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"儉，美德也，過儉則為慳吝，為鄙嗇，反傷雅道；讓，懿行也，過讓則為足恭，為曲謹，多出機心。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"毋憂拂意，毋喜快心，毋恃久安，毋憚初難。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"世人以心愜處為樂，卻被樂心引入苦處；達士以心拂處為樂，終由苦心換得樂來。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"居盈滿者，如水之將溢未溢，切忌再加一滴；處危急者，如木之將折未折，切忌再加一搦。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"仁人心地寬舒，便福厚而慶長，事事成個寬舒氣象；鄙夫念頭迫促，便福薄而澤短，事事得個迫促規模。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"性躁心粗者，一事無成；心和氣平者，百福自集。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"用人不宜刻，刻則思效者去；交友不宜濫，濫則貢諛者來。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"風斜雨急處，要立得腳定；花濃柳豔處，要著得眼高；路危徑險處，要回得頭早。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"節義之人濟以和衷，纔不啟忿爭之路；功名之士承以謙德，方不開嫉妒之門。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"事稍拂逆，便思不如我的人，則尤怨自消；心稍怠荒，便思勝似我的人，則精神自奮。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"不可乘喜而輕諾，不可因醉而生嗔，不可乘快而多事，不可因倦而鮮終。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"善讀書者，要讀到手舞足蹈處，方不落筌蹄；善觀物者，要觀到心融神洽時，方不泥跡象。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"口乃心之門，守口不密，洩盡真機；意乃心之足，防意不嚴，走盡邪蹊。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"責人者，原無過於有過之中，則情平；責己者，求有過於無過之內，則德進。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"桃李雖豔，何如松蒼柏翠之堅貞；梨杏雖甘，何如橘綠橙黃之馨冽。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"爭先的徑路窄，退後一歩自寬平一歩。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"忙處不亂性，須閒處心神養得清。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"孤雲出岫，去留一無所係。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"悠長之趣，不得於醲釅，而得於啜菽飲水。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"水流而境無聲，得處喧見寂之趣。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"出世之道，即在渉世中，不必絶人以逃世。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"徜徉於山林泉石之閒，而塵心漸息。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"花居盆內，終乏生機，鳥入籠中，便減天趣。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"簾櫳高敞，看青山綠水呑吐雲煙，識乾坤之自在。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"林間松韻，石上泉聲，靜裡聴來，識天地自然鳴佩。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"心地上無風濤，隨在皆青山綠樹。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"寵辱不驚，閑看庭前花開花落。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"伏久者，飛必高，開先者，謝獨早。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true},{"zh":"意所偶會，便成佳境，物出天然，纔見真機。","author":"洪應明","work":"《菜根譚》","source":"https://zh.wikisource.org/zh-hant/菜根譚","excerpt":true}];
function dailyQuote(date=new Date()){
 const parts=new Intl.DateTimeFormat('en',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(date);
 const val=type=>Number(parts.find(p=>p.type===type).value);
 const day=Math.floor((Date.UTC(val('year'),val('month')-1,val('day'))-Date.UTC(2026,9,11))/86400000);
 return DAILY_QUOTES[((day%DAILY_QUOTES.length)+DAILY_QUOTES.length)%DAILY_QUOTES.length];
}
function dailyQuoteCopy(){const q=dailyQuote();return '<div class="eyebrow">每日名言佳句</div><p class="quote-zh">'+e(q.zh)+'</p>'+(q.en?'<p class="quote-en" lang="en">'+e(q.en)+'</p>':'')+'<a class="quote-author" href="'+e(q.source)+'" target="_blank" rel="noopener">— '+e(q.author)+' · '+e(q.work)+(q.excerpt?'（節錄）':'')+' ↗</a>'}
function refreshDailyQuote(){const el=$('.daily-quote-copy');if(el)el.innerHTML=dailyQuoteCopy()}
function scheduleDailyQuote(){const now=Date.now(),taipeiNow=now+8*3600000;setTimeout(()=>{refreshDailyQuote();scheduleDailyQuote()},86400000-((taipeiNow%86400000)+86400000)%86400000+1000)}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refreshDailyQuote()});

function home(){const totals=learningTotals();return intro('今天，練習一點。','從一題開始，把不熟悉的地方慢慢讀懂。',true)+stats(totals)+`<div class="grid"><section class="card mode-card"><div class="mode-header"><div class="row between"><h2>開始一輪練習</h2><span class="badge">隨機 · 不重複抽題</span></div>${modeTabs()}</div><div class="fields"><div><label>題目年份（民國）</label><div class="yearrow"><input id="from" type="number" min="1" max="200" value="${config.from}" aria-label="起始年份"><span>至</span><input id="to" type="number" min="1" max="200" value="${config.to}" aria-label="結束年份"></div><div class="btn-group" style="margin-top:8px">${[3,5,10].map(n=>`<button class="small" data-years="${n}">近 ${n} 年</button>`).join('')}</div></div><div><label for="count">這次練習幾題？</label><input id="count" type="number" min="1" max="200" value="${config.count}"><div class="fine" style="margin-top:8px">可設定 1～200 題</div></div></div><div class="row between"><h3>各科出題比例</h3><button class="plain small" id="equal">平均分配</button></div><div class="fine">以權重換算比例；0 代表不出題。申論只顯示有申論的科目。</div><div class="weights" id="weights">${weightsUI()}</div><div class="foot"><div class="row between"><span class="muted">符合年份與題型</span><b>${pool().length} 題</b></div><button class="primary start" id="start">開始練習 <span style="float:right">→</span></button>${session?'<button class="start outline" id="resume">繼續上次練習 →</button>':''}<div class="fine" style="margin-top:12px">題數不足時會提示實際可練題數；每輪不重複。</div></div></section><section><div class="quote"><svg class="cosmos" viewBox="0 0 200 170" fill="none" aria-hidden="true"><defs><radialGradient id="planet-light" cx=".3" cy=".2" r=".85"><stop stop-color="#b4e4f3" stop-opacity=".18"/><stop offset="1" stop-color="#84a9df" stop-opacity=".03"/></radialGradient></defs><circle cx="111" cy="106" r="60" fill="url(#planet-light)" stroke="#cdf7ff" stroke-opacity=".48"/><path d="M60 75c17-14 35-20 54-20" stroke="#cdf7ff" stroke-opacity=".2" stroke-linecap="round"/><ellipse cx="111" cy="106" rx="95" ry="24" transform="rotate(-25 111 106)" stroke="#cdf7ff" stroke-opacity=".38"/><path d="m35 30 2 7 7 2-7 2-2 7-2-7-7-2 7-2Z" fill="#cdf7ff" fill-opacity=".5"/><circle cx="169" cy="29" r="2" fill="#cdf7ff" fill-opacity=".6"/><circle cx="15" cy="84" r="1.3" fill="#cdf7ff" fill-opacity=".4"/></svg><div class="daily-quote-copy">${dailyQuoteCopy()}</div></div><div class="card"><div class="row between"><h2>各科掌握度</h2><span class="fine">累積正確率</span></div>${subjs.map(k=>{const {attempts:a,right:b}=totals.subjects[k],pct=a?Math.round(b/a*100):0;return `<div class="subject-line"><div class="row between"><span>${k}</span><span class="muted">${a?pct+'%':'尚未練習'}</span></div><div class="progress"><i style="width:${pct}%"></i></div></div>`}).join('')}</div><div class="notice">官方答案與外部詳解分開呈現。較早年份的法律題，練習時請一併核對現行法規。</div></section></div>`}
function start(wrong=false){if(config.from>config.to||!Number.isInteger(config.count)||config.count<1||config.count>200){toast('請確認年份順序與題數（1～200）。');return}let all=pool();if(wrong)all=filteredWrong();let list=wrong?shuffle(all).slice(0,config.count):weightedSample(all,config.count,config.weights);if(!list.length){toast(wrong?'這個範圍還沒有待複習題目。':'沒有符合設定的題目，請調整年份或比例。');return}if(list.length<config.count)toast(`題庫不足，本輪共有 ${list.length} 題。`);session={ids:list.map(q=>q.id),index:0,type:mode,answers:{},started:Date.now(),wrong};save();tab='practice';render();window.scrollTo(0,0)}
function formatExamText(value,paragraphs=false){
 const lines=String(value??'').replace(/\r\n?/g,'\n').split('\n');let out='',previous='',blank=false;
 const item=/^(?:[（(][一二三四五六七八九十百\d]+[）)]|[一二三四五六七八九十]+[、．.]|\d+[、．.)]|[①-⑳])/;
 const cjk=/[\p{Script=Han}\p{Script=Hiragana}\p{Script=Katakana}，。！？；：、「」『』（）《》]/u;
 for(const raw of lines){const line=raw.trim().replace(/[\t ]+/g,' ');if(!line){if(out)blank=true;continue}
  if(!out)out=line;
  else if(blank||item.test(line)||/^(?:請依|請閱讀).*第\s*\d+\s*題/.test(previous)||/^(?:作文|申論題?)\s*[:：]/.test(previous))out+='\n\n'+line;
  else if(paragraphs&&/^\s/.test(raw)&&/[.!?。！？]$/.test(previous))out+='\n\n'+line;
  else out+=((cjk.test(previous.at(-1))&&cjk.test(line[0]))||(/[A-Za-z]-$/.test(previous)&&/^[a-z]/.test(line))?'':' ')+line;
  previous=line;blank=false;
 }
 return out;
}

function translationPanel(q){
 const tr=q.translation;if(!tr)return '';
 return '<section class="translation-panel" aria-label="中文翻譯"><h3>中文翻譯</h3><div class="fine">依原文翻譯；填空處依官方答案補全。</div><div class="answertext">'+e(tr.text)+'</div><ol class="translation-options">'+tr.options.map((o,i)=>'<li><b>'+('ABCD'[i])+'.</b><span>'+e(o)+'</span></li>').join('')+'</ol>'+(tr.context?'<details class="translation-context"><summary>共用文章中文翻譯</summary><div class="answertext">'+e(tr.context)+'</div></details>':'')+'</section>'
}
function question(){let q=QUESTION_INDEX.get(session.ids[session.index]);if(!q){session=null;save();tab='home';return home()}let done=session.answers[q.id],selected=done?.selected;return `<div class="practice-position fine">${session.wrong?'錯題演練':'隨機練習'} · 第 ${session.index+1} / ${session.ids.length} 題</div><div class="progress" style="height:6px;margin-bottom:23px;background:rgba(189,203,241,.15);border-radius:6px"><i style="width:${(session.index+1)/session.ids.length*100}%;background:linear-gradient(90deg,#72c0dc,#afa6dc)"></i></div><div class="card" style="max-width:950px;margin:auto"><div class="row between question-meta"><div class="question-info"><span class="pill">${e(q.subject)}</span> <span class="muted">${q.year} 年普考 · 原卷第 ${e(q.number)} 題</span></div><button class="plain small" id="pause">稍後繼續</button></div><div class="qbody">${q.context?`<div class="question-context">${e(formatExamText(q.context,true))}</div>`:''}<div class="question-text">${e(formatExamText(q.text))}</div></div>${q.type==='mc'?'<div class="options">'+q.options.map((o,i)=>{let a='ABCD'[i];return `<button class="option ${done?(q.answers.includes(a)?'correct':selected===a?'wrong':''):''}" data-answer="${a}" ${done?'disabled':''}><b>${a}</b><span>${e(formatExamText(o))}</span></button>`}).join('')+'</div>':`<label for="draft">我的作答 <span class="muted">自動儲存草稿</span></label><textarea id="draft" placeholder="先列出概念與架構，再展開論述…">${e(DATA.drafts[q.id]||'')}</textarea><div class="row between"><span class="fine" id="wordcount">${(DATA.drafts[q.id]||'').length} 字</span><label><input id="review" type="checkbox" ${DATA.records[q.id]?.review?'checked':''}> 列入待複習</label></div><div class="notice">申論題不以選擇題方式判分。可參考外部擬答，或複製題目與草稿詢問 AI；參考內容並非官方評分。</div>`}${done&&q.type==='mc'?`<div class="feedback ${done.correct?'':'bad'}"><b>${done.correct?'答對了，繼續保持。':'這題先留下，之後再練。'}</b><div class="answer-summary"><span>你的答案：${e(done.selected)}</span><span>官方答案：${q.answers.join(' 或 ')}${q.corrected?'（採用更正答案卷）':''}</span></div></div>`:''}${done&&q.type==='mc'?translationPanel(q):''}${(done&&!done.correct)||DATA.records[q.id]?.wrong||DATA.records[q.id]?.review?errorEditor(q):''}<div class="qtools"><a class="small" href="${e(q.source)}" target="_blank" rel="noopener">原始試卷 ↗</a>${q.answerSource?`<a class="small" href="${e(q.answerSource)}" target="_blank" rel="noopener">官方答案 ↗</a>`:''}<button class="small" id="solutions" aria-expanded="false" aria-controls="solution-links">現成詳解連結 ↗</button><button class="primary small" id="copy-prompt">複製題目問 AI</button></div><div id="solution-links" hidden>${solutionPanel(q)}</div><div class="foot"><div class="row between note-label"><label for="note">我的筆記</label><button class="plain small" data-tab="notes">查看全部筆記 →</button></div><textarea id="note" style="min-height:85px" placeholder="寫下易混淆的觀念，或記錄解題提醒…">${e(DATA.notes[q.id]||'')}</textarea><div class="row between question-nav"><button id="prev" ${session.index?'':'disabled'}>← 上一題</button><button class="primary" id="next">${session.index===session.ids.length-1?'完成本輪':'下一題 →'}</button></div>${!done&&q.type==='mc'?'<div class="fine" style="margin-top:8px">可略過；未作答不計入正確率。</div>':''}</div></div>`}
function choose(a){let q=QUESTION_INDEX.get(session.ids[session.index]);if(session.answers[q.id])return;let ok=q.answers.includes(a),r=DATA.records[q.id]??={attempts:0,right:0};r.attempts++;r.right+=ok?1:0;r.last=Date.now();r.lastAnswer=a;if(!ok){r.lastWrongAnswer=a;r.wrong=true;r.wrongCount=(r.wrongCount||0)+1}session.answers[q.id]={selected:a,correct:ok};save();render()}
function finish(){let answers=Object.values(session.answers),correct=answers.filter(a=>a.correct).length;DATA.history.unshift({date:Date.now(),type:session.type,total:session.ids.length,answered:answers.length,correct});DATA.history=DATA.history.slice(0,200);let old=session;session=null;save();tab='result';nav();$('#app').innerHTML=intro('這一輪，完成了。','看過的每一題，都是你累積的進步。')+`<div class="card"><div class="result-score">${old.type==='mc'?correct+' / '+answers.length:old.ids.length+' 題'}</div><p class="muted">${old.type==='mc'?`答對 ${correct} 題 · 答錯 ${answers.length-correct} 題 · 略過 ${old.ids.length-answers.length} 題`:'申論草稿與筆記已儲存。'}</p><div class="btn-group"><button class="primary" data-tab="home">回到練習室</button><button data-tab="wrong">查看錯題本</button></div></div><div class="card"><h2>本輪題目</h2>${old.ids.map(id=>{let q=QUESTION_INDEX.get(id),a=old.answers[id];return `<div class="list-item"><span class="pill">${e(q.subject)}</span> <span class="muted">${q.year} 年 · ${old.type==='mc'?(a?(a.correct?'✓ 正確':'✕ 錯誤'):'未作答'):'草稿已保存'}</span><p class="truncate">${e(formatExamText(q.text))}</p><button class="small" data-open="${id}">再看這題</button></div>`}).join('')}</div>`}
const ERROR_REASONS=['觀念不清','相似概念混淆','漏看題目','記憶不熟','英文不懂','其他'];
let wrongReason='all',wrongTag='all';
function normalizeTags(value){const seen=new Set();return String(value??'').split(/[,，、;；\n]+/).map(t=>t.trim().slice(0,20)).filter(t=>{const key=t.toLocaleLowerCase();if(!t||seen.has(key))return false;seen.add(key);return true}).slice(0,8)}
function getErrorMeta(id){const m=DATA.errorMeta?.[id]||{};return {reason:ERROR_REASONS.includes(m.reason)?m.reason:'',tags:normalizeTags(Array.isArray(m.tags)?m.tags.join('、'):'')}}
function updateErrorMeta(id,patch){if(!QUESTION_INDEX.has(id))return;const m=getErrorMeta(id);if(Object.hasOwn(patch,'reason'))m.reason=ERROR_REASONS.includes(patch.reason)?patch.reason:'';if(Object.hasOwn(patch,'tags'))m.tags=normalizeTags(Array.isArray(patch.tags)?patch.tags.join('、'):patch.tags);DATA.errorMeta??={};DATA.errorMeta[id]=m;save()}
function reviewQuestions(){return pool().filter(q=>DATA.records[q.id]?.wrong||DATA.records[q.id]?.review)}
function filteredWrong(){return reviewQuestions().filter(q=>{const m=getErrorMeta(q.id);return (wrongReason==='all'||(wrongReason==='unclassified'?!m.reason:m.reason===wrongReason))&&(wrongTag==='all'||m.tags.includes(wrongTag))})}
function errorCounts(qs){const reasons={},tags={};for(const q of qs){const m=getErrorMeta(q.id);const reason=m.reason||'未分類';reasons[reason]=(reasons[reason]||0)+1;for(const tag of m.tags)tags[tag]=(tags[tag]||0)+1}return {reasons,tags}}
function errorBadges(q){const m=getErrorMeta(q.id);return '<div class="error-badges"><span class="reason-badge">'+e(m.reason||'未分類')+'</span>'+m.tags.map(tag=>'<span class="concept-tag">'+e(tag)+'</span>').join('')+'</div>'}
function errorEditor(q){const m=getErrorMeta(q.id);return '<section class="error-editor"><h3>錯誤原因與觀念標籤</h3><div class="fields"><div><label for="reason-'+e(q.id)+'">這題為什麼答錯？</label><select id="reason-'+e(q.id)+'" data-error-reason="'+e(q.id)+'"><option value="">尚未分類</option>'+ERROR_REASONS.map(r=>'<option value="'+e(r)+'" '+(m.reason===r?'selected':'')+'>'+e(r)+'</option>').join('')+'</select></div><div><label for="tags-'+e(q.id)+'">我容易混淆的觀念</label><input id="tags-'+e(q.id)+'" type="text" data-error-tags="'+e(q.id)+'" value="'+e(m.tags.join('、'))+'" placeholder="例如：行政處分、行政命令"><div class="fine">多個標籤請用逗號或頓號分隔</div></div></div><div class="fine error-save-state" role="status">修改後自動儲存</div></section>'}
function showErrorEditor(id){const q=QUESTION_INDEX.get(id);if(!q)return;$('#modal').innerHTML='<div class="row between"><h2>錯題分類</h2><button class="small" data-close-dialog>完成</button></div><div class="fine">'+q.year+' 年 · '+e(q.subject)+' · 第 '+e(q.number)+' 題</div><p class="truncate">'+e(formatExamText(q.text))+'</p>'+errorEditor(q);$('#modal').showModal()}
function buildWrongExport(qs=filteredWrong()){
 const counts=errorCounts(qs),subjects={},contexts=new Map();for(const q of qs){subjects[q.subject]=(subjects[q.subject]||0)+1;if(q.context&&!contexts.has(q.context))contexts.set(q.context,contexts.size+1)}
 const reasons=Object.entries(counts.reasons).sort((a,b)=>b[1]-a[1]).map(([k,n])=>k+'：'+n+' 題').join('；')||'無';
 const tags=Object.entries(counts.tags).sort((a,b)=>b[1]-a[1]).map(([k,n])=>k+'：'+n+' 題').join('；')||'尚未標記';
 const lines=['行政日課｜錯題分析資料','匯出時間：'+new Date().toLocaleString('zh-TW',{timeZone:'Asia/Taipei'})+'（台灣時間）',
 '範圍：'+config.from+'–'+config.to+' 年；'+(mode==='mc'?'選擇題':'申論與作文')+'；錯誤原因：'+(wrongReason==='all'?'全部':wrongReason==='unclassified'?'尚未分類':wrongReason)+'；觀念標籤：'+(wrongTag==='all'?'全部':wrongTag),
 '本次匯出：'+qs.length+' 題（包含目前篩選結果的所有分頁）','',
 '請用繁體中文、淺白易懂的方式分析這份錯題資料：',
 '1. 依科目整理反覆出錯的觀念、相似概念與常見錯誤原因，依待複習題數和累積答錯次數列出優先順序。',
 '2. 將我自行標記的原因與你根據題目推測的原因分開說明。若缺少筆記或錯誤答案，請標示資料不足，不要直接斷定我不懂哪個觀念。',
 '3. 用比較表和生活例子說明容易混淆的概念，提供下次作答的判斷步驟。',
 '4. 提供可執行的複習順序，再出 5 道針對弱點的練習題，答案與詳解置於最後。',
 '5. 法律題請核對現行官方法規並附來源，區分考試當年的官方答案與現行規定；未查證的內容請明確標示。申論題沒有官方選擇題答案，不可據此判分。',
 '', '統計摘要（以題目計數，一題可能有多個標籤）',
 '科目：'+Object.entries(subjects).map(([k,n])=>k+'：'+n+' 題').join('；'),
 '錯誤原因：'+reasons,'觀念標籤：'+tags,''];
 for(const [i,q] of qs.entries()){
  const r=DATA.records[q.id]||{},m=getErrorMeta(q.id),last=r.lastAnswer||'';
  const wrongAnswer=r.lastWrongAnswer||(last&&q.answers&&!q.answers.includes(last)?last:'');
  lines.push('──────── 題目 '+(i+1)+' ────────','題目 ID：'+q.id,q.year+' 年普考一般行政｜'+q.subject+'｜原卷第 '+q.number+' 題');
  if(q.context)lines.push('共用文章：文章 '+contexts.get(q.context)+'（全文見檔案末尾）');
  lines.push('題幹：',formatExamText(q.text));
  if(q.options)lines.push(...q.options.map((o,j)=>'ABCD'[j]+'. '+formatExamText(o)));
  if(q.type==='mc')lines.push('最近一次答案：'+(last||'未保存'),'最後一次錯誤答案：'+(wrongAnswer||'未保存；不能由最近一次答案推定'),
   '官方答案：'+q.answers.join(' 或 ')+(q.corrected?'（採用官方更正答案）':''));
  else lines.push('我的申論草稿：',DATA.drafts[q.id]||'尚未填寫');
  lines.push('累積練習：'+(r.attempts||0)+' 次；答對：'+(r.right||0)+' 次；答錯：'+(r.wrongCount||0)+' 次',
   '收錄狀態：'+(r.wrong?'曾答錯、待複習':'手動列入待複習'),'錯誤原因：'+(m.reason||'尚未分類'),'觀念標籤：'+(m.tags.join('、')||'尚未標記'),
   '我的筆記：',DATA.notes[q.id]?.trim()||'尚未填寫','官方試卷：'+q.source);
  if(q.answerSource)lines.push('官方答案卷：'+q.answerSource);
  lines.push('');
 }
 if(contexts.size){lines.push('════════ 共用文章全文 ════════');for(const [text,id] of contexts)lines.push('文章 '+id,formatExamText(text,true),'')}
 return lines.join('\n');
}
function exportWrongQuestions(){const qs=filteredWrong();if(!qs.length){toast('目前篩選範圍沒有可下載的錯題。');return}
 const parts=new Intl.DateTimeFormat('en',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const date=['year','month','day'].map(k=>parts.find(p=>p.type===k).value).join('-');
 const name='行政日課-錯題-'+(mode==='mc'?'選擇題':'申論')+'-'+config.from+'-'+config.to+'-'+date+'.txt';
 const url=URL.createObjectURL(new Blob(['\ufeff'+buildWrongExport(qs)],{type:'text/plain;charset=utf-8'}));
 const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
 toast('已下載 '+qs.length+' 題，可將文字檔上傳給 AI 分析。');
}

function wrong(){const all=reviewQuestions(),counts=errorCounts(all),tags=Object.keys(counts.tags).sort((a,b)=>counts.tags[b]-counts.tags[a]||a.localeCompare(b,'zh-TW'));if(wrongTag!=='all'&&!tags.includes(wrongTag))wrongTag='all';const qs=filteredWrong();page=Math.min(page,Math.max(0,Math.ceil(qs.length/20)-1));return `<div class="card mode-card wrong-card" aria-label="錯題演練"><div class="mode-header compact">${modeTabs()}</div><div class="fields"><div><label for="wrong-reason">依錯誤原因篩選</label><select id="wrong-reason"><option value="all">全部原因</option><option value="unclassified" ${wrongReason==='unclassified'?'selected':''}>尚未分類（${counts.reasons['未分類']||0} 題）</option>${ERROR_REASONS.map(r=>`<option value="${e(r)}" ${wrongReason===r?'selected':''}>${e(r)}（${counts.reasons[r]||0} 題）</option>`).join('')}</select></div><div><label for="wrong-tag">依觀念標籤篩選</label><select id="wrong-tag"><option value="all">全部標籤</option>${tags.map(t=>`<option value="${e(t)}" ${wrongTag===t?'selected':''}>${e(t)}（${counts.tags[t]} 題）</option>`).join('')}</select></div></div>${tags.length?`<div class="error-topics"><h3>常錯觀念 · 待複習題數</h3><div class="btn-group">${tags.slice(0,8).map(t=>`<button class="small ${wrongTag===t?'primary':''}" data-wrong-tag="${e(t)}">${e(t)} · ${counts.tags[t]} 題</button>`).join('')}</div></div>`:''}<div class="row between"><span>待複習 ${all.length} 題 · 符合篩選 ${qs.length} 題 <span class="fine">${config.from}–${config.to} 年</span></span><div class="btn-group wrong-actions"><button id="download-wrong" ${qs.length?'':'disabled'}>下載錯題給 AI ↓</button><button class="primary" id="wrong-start" ${qs.length?'':'disabled'}>演練篩選結果 ${Math.min(config.count,qs.length)} 題 →</button></div></div><p class="fine export-hint">下載目前篩選的全部 ${qs.length} 題，包含其他分頁；附題目、答案、原因、標籤、筆記與 AI 分析提示。</p>${qs.length?qs.slice(page*20,page*20+20).map(q=>`<div class="list-item"><span class="pill">${e(q.subject)}</span> <span class="muted">${q.year} 年 · 累積答錯 ${DATA.records[q.id]?.wrongCount||0} 次</span><p class="truncate">${e(formatExamText(q.text))}</p>${errorBadges(q)}<div class="btn-group"><button class="small" data-open="${e(q.id)}">練習這題</button><button class="small" data-error-edit="${e(q.id)}">編輯原因與標籤</button><button class="plain small" data-remove="${e(q.id)}">已熟悉，移出</button></div></div>`).join('')+pagination(qs.length):'<div class="empty">'+(all.length?'沒有符合原因與標籤的錯題，請調整篩選。':'目前沒有待複習題目。<br>先開始一輪練習，錯題會自動收進這裡。')+'</div>'}</div>`}

function pagination(n){return `<div class="row between" style="margin-top:20px"><button id="pageprev" ${page?'':'disabled'}>← 上一頁</button><span class="muted">${page+1} / ${Math.max(1,Math.ceil(n/20))}</span><button id="pagenext" ${((page+1)*20>=n)?'disabled':''}>下一頁 →</button></div>`}
let search='',bankYear='all',bankSub='all';function filtered(){return BANK.filter(q=>q.type===mode&&(bankYear==='all'||q.year===+bankYear)&&(bankSub==='all'||q.subject===bankSub)&&(!search||SEARCH_INDEX.get(q.id)?.includes(search)))}
function bank(){let qs=filtered();return intro('十年考題，隨時翻閱。','依現行考科整理歷年題目，每題保留官方試卷連結。')+`<div class="card mode-card"><div class="mode-header compact">${modeTabs()}</div><div class="fields"><div><label>年份</label><select id="bankyear"><option value="all">全部年份</option>${[...new Set(BANK.map(q=>q.year))].sort((a,b)=>b-a).map(y=>`<option ${String(y)===bankYear?'selected':''}>${y}</option>`).join('')}</select></div><div><label>科目</label><select id="banksub"><option value="all">全部科目</option>${[...new Set(BANK.map(q=>q.subject))].map(k=>`<option ${k===bankSub?'selected':''}>${e(k)}</option>`).join('')}</select></div></div><label for="search">搜尋題目</label><input id="search" type="search" value="${e(search)}" placeholder="例如：行政處分、權力分立…"><p class="fine" style="margin-top:15px">共 ${qs.length} 題</p>${qs.slice(page*20,page*20+20).map(q=>`<div class="list-item"><span class="pill">${e(q.subject)}</span> <span class="muted">${q.year} 年 · 原卷第 ${e(q.number)} 題</span><p class="truncate">${e(formatExamText(q.text))}</p><button class="small" data-open="${q.id}">開始作答 →</button></div>`).join('')||'<div class="empty">没有符合條件的題目。</div>'}${pagination(qs.length)}</div>`}
let notesSearch='',notesSubject='all',deletedNote=null;
function saveNote(id,value){if(deletedNote?.id===id)deletedNote=null;DATA.notes[id]=value;DATA.noteUpdated??={};DATA.noteUpdated[id]=Date.now();save()}
function deleteNote(id){if(typeof DATA.notes[id]!=='string')return false;deletedNote={id,text:DATA.notes[id],updated:DATA.noteUpdated?.[id]};delete DATA.notes[id];if(DATA.noteUpdated)delete DATA.noteUpdated[id];save();return true}
function restoreDeletedNote(){if(!deletedNote)return;const item=deletedNote;DATA.notes[item.id]=item.text;DATA.noteUpdated??={};if(item.updated!==undefined)DATA.noteUpdated[item.id]=item.updated;deletedNote=null;save()}
function noteEntries(){return Object.keys(DATA.notes).map(id=>QUESTION_INDEX.get(id)).filter(q=>q&&typeof DATA.notes[q.id]==='string'&&DATA.notes[q.id].trim()).sort((a,b)=>(Number(DATA.noteUpdated?.[b.id])||Number(DATA.records[b.id]?.last)||0)-(Number(DATA.noteUpdated?.[a.id])||Number(DATA.records[a.id]?.last)||0)||b.year-a.year||Number(a.number)-Number(b.number))}
function filteredNotes(){const term=notesSearch.trim().toLocaleLowerCase();return noteEntries().filter(q=>(notesSubject==='all'||q.subject===notesSubject)&&(!term||[DATA.notes[q.id],q.text,q.context||'',...(q.options||[]),q.subject,String(q.year),getErrorMeta(q.id).reason,...getErrorMeta(q.id).tags].join(' ').toLocaleLowerCase().includes(term)))}
function notes(){const all=noteEntries(),qs=filteredNotes();page=Math.min(page,Math.max(0,Math.ceil(qs.length/20)-1));return intro('我的筆記。','把理解過的觀念留下，下次複習更容易。')+(deletedNote?'<div class="notice row between deleted-note-notice"><span>筆記已刪除</span><button class="small" id="undo-delete-note">復原</button></div>':'')+`<section class="card notes-filters"><div class="fields"><div><label for="notes-subject">科目</label><select id="notes-subject"><option value="all">全部科目</option>${subjs.map(k=>`<option value="${e(k)}" ${notesSubject===k?'selected':''}>${e(k)}</option>`).join('')}</select></div><div><label for="notes-search">搜尋筆記或題目</label><input id="notes-search" type="search" value="${e(notesSearch)}" placeholder="例如：行政處分、BSC、114…"></div></div><div class="fine">共 <span id="notes-total">${all.length}</span> 則筆記 · 符合篩選 ${qs.length} 則 · 包含選擇題與申論題</div></section>${qs.length?qs.slice(page*20,page*20+20).map(q=>`<article class="card note-entry"><div class="row between note-heading"><div class="note-meta"><span class="pill">${e(q.subject)}</span><span class="muted">${q.year} 年 · 原卷第 ${e(q.number)} 題 · ${q.type==='mc'?'選擇題':'申論與作文'}</span></div><div class="note-actions"><button class="small" data-note-question="${e(q.id)}">查看原題 ↗</button><button class="plain note-delete" data-delete-note="${e(q.id)}" aria-label="刪除 ${e(q.year+' 年 '+q.subject+' 第 '+q.number+' 題筆記')}" title="刪除筆記">${navIcon('trash')}</button></div></div><p class="truncate note-question">${e(formatExamText(q.text))}</p>${getErrorMeta(q.id).reason||getErrorMeta(q.id).tags.length?errorBadges(q):''}<div class="note-content">${e(DATA.notes[q.id])}</div><details class="note-editor"><summary>編輯筆記 <span class="fine">自動儲存</span></summary><textarea data-note-edit="${e(q.id)}" aria-label="${e(q.year+' 年 '+q.subject+' 第 '+q.number+' 題筆記')}">${e(DATA.notes[q.id])}</textarea><div class="fine note-save-state" role="status"></div></details></article>`).join('')+pagination(qs.length):'<div class="card empty">'+(all.length?'沒有符合篩選條件的筆記。':'還沒有筆記。<br>作答頁下方的「我的筆記」會自動儲存並顯示在這裡。')+'</div>'}`}
function showNoteQuestion(id){const q=QUESTION_INDEX.get(id);if(!q)return;$('#modal').innerHTML='<div class="row between"><h2>'+e(q.subject)+' · '+q.year+' 年</h2><button class="small" data-close-dialog>關閉</button></div><div class="fine">原卷第 '+e(q.number)+' 題</div><div class="qbody">'+(q.context?'<div class="question-context">'+e(formatExamText(q.context,true))+'</div>':'')+'<div class="question-text">'+e(formatExamText(q.text))+'</div></div>'+(q.options?'<ol class="translation-options">'+q.options.map((o,i)=>'<li><b>'+('ABCD'[i])+'.</b><span>'+e(formatExamText(o))+'</span></li>').join(''):'')+(q.answers?'<div class="notice">官方答案：'+e(q.answers.join(' 或 '))+'</div>':'')+'<div class="qtools"><a href="'+e(q.source)+'" target="_blank" rel="noopener">官方原卷 ↗</a></div>';$('#modal').showModal()}

function records(){return intro('看見自己的累積。','進度儲存在這個瀏覽器，可於「題庫與備份」匯出帶到其他裝置。')+stats()+`<div class="card"><h2>練習紀錄</h2>${DATA.history.length?DATA.history.map(h=>`<div class="list-item row between"><div><b>${h.type==='mc'?'選擇題':'申論與作文'} · ${h.total} 題</b><div class="fine">${new Date(h.date).toLocaleString('zh-TW',{timeZone:'Asia/Taipei'})}</div></div><span>${h.type==='mc'?`${h.correct} / ${h.answered} 答對`:'完成'}</span></div>`).join(''):'<div class="empty">完成一輪後，練習紀錄會顯示在這裡。</div>'}</div>`}
function settings(){return intro('題庫會長大，進度也留好。','新增年份、匯入考題與備份學習紀錄。')+`<div class="grid"><div><div class="card"><h2>官方題庫收錄狀況</h2><p class="muted">106–115 年普考一般行政 · ${PAPERS.length} 份科目試卷</p><div class="scroll"><table><thead><tr><th>年度</th><th>考卷</th><th>選擇題</th><th>申論組</th><th>來源</th></tr></thead><tbody>${[...new Set(PAPERS.map(p=>p.year))].sort((a,b)=>b-a).map(y=>{let ps=PAPERS.filter(p=>p.year===y);return `<tr><td>${y}</td><td>${ps.length}</td><td>${BANK.filter(q=>q.year===y&&q.type==='mc').length}</td><td>${BANK.filter(q=>q.year===y&&q.type==='essay').length}</td><td><a href="https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=${y+1911}" target="_blank" rel="noopener">官方 ↗</a></td></tr>`}).join('')}</tbody></table></div><div class="notice">作文及公文可能以整組呈現；選擇題採用官方答案，更正卷中的多答案皆接受。PDF 轉換如有排版疑義，可開原卷核對。</div></div><div class="card"><h2>新增或更新考題</h2><p class="muted">匯入標準 JSON 題庫，同 ID 的題目會更新；不同 ID 的題目會新增。更新不會清除你的作答紀錄。</p><label for="bankfile">選擇題庫 JSON</label><input id="bankfile" type="file" accept=".json,application/json"><div class="btn-group" style="margin-top:18px"><button id="schema">下載匯入範例</button><button id="check-updates">查詢新年度官方考卷 ↗</button></div><p class="fine" style="margin-top:12px">可在這裡更新題庫；目前不會在背景自動下載新卷。</p></div></div><div><div class="card"><h2>備份與還原</h2><p class="muted">包含錯題、作答紀錄、筆記、申論草稿、設定與新增考題。</p><button class="primary" id="export">匯出完整備份 ↓</button><div class="foot"><label for="backupfile">匯入備份（合併到目前紀錄）</label><input id="backupfile" type="file" accept=".json,application/json"></div></div><div class="card"><h2>現成詳解與 AI 提問</h2><p>每題可展開公職王、躍題庫與阿摩的外部解答或搜尋入口。</p><div class="notice">按「複製題目問 AI」，會複製年份、科目、題目、選項、共用閱讀文章與官方答案；申論也會包含你的作答草稿。</div><p class="fine">貼到 ChatGPT 就能詢問。外部來源可能需登入或付費，解說是否完整依各網站而定。</p></div></div></div>`}
function prompt(q){const meta=getErrorMeta(q.id);return `請用繁體中文、淺白易懂的方式解說這道 ${q.year} 年普考一般行政 ${e(q.subject)} ${q.type==='mc'?'選擇題':'申論題'}。\n${formatExamText(q.context||'',true)}\n${formatExamText(q.text)}\n${(q.options||[]).map((o,i)=>'ABCD'[i]+'. '+formatExamText(o)).join('\n')}\n${q.answers?'官方答案：'+q.answers.join(' 或 '):''}\n${q.type==='essay'?'我的作答：\n'+(DATA.drafts[q.id]||'尚未作答'):''}\n${q.type==='mc'?'先說答案，再逐一解釋選項，最後用例子整理判斷方法。':'提供破題、概念說明、分段架構與具體改進建議。'}涉及法規時請核對現行官方法規，區別考試當年的答案與現行規定，附來源；沒有查證就明確標示未查證。不要編造法條或官方評分標準。\n${meta.reason?'我的錯誤原因：'+meta.reason+'\n':''}${meta.tags.length?'我想釐清的觀念：'+meta.tags.join('、')+'\n':''}官方試卷：${q.source}`}
function solutionSources(q){
 const links=[];
 if(q.year===115&&['行政學概要','政治學概要'].includes(q.subject))links.push({title:'躍題庫：同卷考題與詳解',url:'https://www.jumpvault.tw/%E4%B8%80%E8%88%AC%E8%A1%8C%E6%94%BF/115080_'+(q.subject==='行政學概要'?'0304':'0302')+'/',note:'已確認對應考卷，進入後查看原卷第 '+q.number+' 題。詳解開放範圍依來源網站為準。'});
 const annual={113:'https://www.public.com.tw/exampoint/2024-kp',114:'https://www.public.com.tw/exampoint/2025-kp',115:'https://www.public.com.tw/exampoint/2026-kp'};
 links.push({title:annual[q.year]?'公職王：'+q.year+' 年高普考解答':'公職王：普考一般行政歷年解答',url:annual[q.year]||'https://www.public.com.tw/previousexam?mode=0&page=1&subject=ab0003&type=ao0031&year='+q.year,note:'解答卷入口；請選「普考一般行政」的「'+q.subject+'」，再找原卷第 '+q.number+' 題。各卷解析詳盡程度不同。'});
 const terms=q.year+' 普考 '+q.subject+' '+q.text.replace(/\s+/g,' ').slice(0,70);
 links.push({title:'阿摩：搜尋此題討論',url:'https://www.google.com/search?q='+encodeURIComponent('site:yamol.tw '+terms),note:'以年份、科目與題幹搜尋；尚未確認每題都有討論，部分詳解需登入或付費。'});
 links.push({title:'躍題庫：搜尋同題詳解',url:'https://www.google.com/search?q='+encodeURIComponent('site:jumpvault.tw '+terms),note:'搜尋此題的外部詳解；近期年度及較早年度的開放範圍不同。'});
 return links;
}
function solutionPanel(q){return '<section class="notice"><h3>現成詳解連結</h3><p class="fine">'+e(q.year+' 年普考 · '+q.subject+' · 原卷第 '+q.number+' 題')+'</p>'+solutionSources(q).map(l=>'<div class="list-item"><a href="'+e(l.url)+'" target="_blank" rel="noopener">'+e(l.title)+' ↗</a><div class="fine">'+e(l.note)+'</div></div>').join('')+'<p class="fine" style="margin-top:12px">外部資料不一定有逐題詳解；法律題請留意解說年份。查不到時，可按「複製題目問 AI」貼到 ChatGPT。</p></section>'}
function download(name,obj){let u=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function validateBank(qs){if(!Array.isArray(qs)||!qs.length||qs.length>20000)throw Error('題庫必須是包含 1～20000 題的陣列。');const ids=new Set();for(const q of qs){if(typeof q.id!=='string'||ids.has(q.id)||!Number.isInteger(q.year)||q.year<1||q.year>300||typeof q.subject!=='string'||typeof q.text!=='string'||!['mc','essay'].includes(q.type)||!/^https:\/\//.test(q.source||''))throw Error('題目欄位或來源網址不完整，請參考匯入範例。');ids.add(q.id);if(q.type==='mc'&&(!Array.isArray(q.options)||q.options.length!==4||q.options.some(o=>typeof o!=='string')||!Array.isArray(q.answers)||!q.answers.length||q.answers.some(a=>!['A','B','C','D'].includes(a))))throw Error('選擇題必須有 4 個選項與有效答案。')}return qs}
function mergeBank(qs){let m=new Map(DATA.custom.map(q=>[q.id,q]));qs.forEach(q=>m.set(q.id,q));DATA.custom=[...m.values()];let all=new Map(BANK.map(q=>[q.id,q]));qs.forEach(q=>all.set(q.id,q));BANK=[...all.values()];applyCurrentSyllabus();for(const q of qs)config.weights[q.subject]??=10;save()}
async function importFile(file,backup){if(!file)return;try{let d=JSON.parse(await file.text());if(backup){if(d.format!=='adminDaily.backup.v1'||!d.data||typeof d.data.records!=='object')throw Error('不是有效的行政日課備份。');validateBank(d.data.custom?.length?d.data.custom:[BANK[0]]);for(const k of ['records','notes','drafts','noteUpdated','errorMeta'])DATA[k]={...DATA[k],...(d.data[k]||{})};DATA.history=[...DATA.history,...(d.data.history||[])].filter((v,i,a)=>a.findIndex(x=>x.date===v.date)===i).sort((a,b)=>b.date-a.date).slice(0,200);if(d.data.custom?.length)mergeBank(d.data.custom);save();toast('備份已合併，原有紀錄保留。')}else{let qs=validateBank(Array.isArray(d)?d:d.questions);mergeBank(qs);toast(`已新增或更新 ${qs.length} 題。`)}render()}catch(err){toast('匯入失敗：'+err.message)}}
function render(){nav();$('#app').innerHTML=tab==='practice'&&session?question():({home,wrong,bank,notes,records,settings}[tab]||home)()}
document.addEventListener('click',async ev=>{let b=ev.target.closest('button');if(!b)return;if(b.dataset.deleteNote){if(deleteNote(b.dataset.deleteNote))render();return}if(b.id==='undo-delete-note'){restoreDeletedNote();render();return}if(b.hasAttribute('data-close-dialog')){$('#modal').close();if(tab==='wrong'||tab==='notes')render();return}if(b.dataset.errorEdit){showErrorEditor(b.dataset.errorEdit);return}if(b.dataset.wrongTag){wrongTag=b.dataset.wrongTag;page=0;render();return}if(b.dataset.noteQuestion){showNoteQuestion(b.dataset.noteQuestion);return}if(b.dataset.tab){goto(b.dataset.tab);return}if(b.dataset.mode){mode=b.dataset.mode;page=0;if(mode==='essay'){config.count=Math.min(config.count,5);if(!pool().some(q=>(config.weights[q.subject]||0)>0))for(let q of pool())config.weights[q.subject]=1}save();render();return}if(b.dataset.years){config.to=Math.max(...BANK.map(q=>q.year));config.from=config.to-Number(b.dataset.years)+1;save();render();return}if(b.dataset.answer){choose(b.dataset.answer);return}if(b.dataset.open){let q=QUESTION_INDEX.get(b.dataset.open);session={ids:[q.id],index:0,type:q.type,answers:{},started:Date.now()};save();tab='practice';render();window.scrollTo(0,0);return}if(b.dataset.remove){let r=DATA.records[b.dataset.remove];r.wrong=false;r.review=false;save();render();return}switch(b.id){case 'equal':for(let k of subjs)config.weights[k]=pool().some(q=>q.subject===k)?1:0;save();render();break;case 'start':start();break;case 'wrong-start':start(true);break;case 'download-wrong':exportWrongQuestions();break;case 'resume':tab='practice';mode=session.type;render();break;case 'pause':save();goto('home');break;case 'prev':session.index--;save();render();window.scrollTo(0,0);break;case 'next':if(session.index===session.ids.length-1)finish();else{session.index++;save();render();window.scrollTo(0,0)}break;case 'pageprev':page--;render();break;case 'pagenext':page++;render();break;case 'solutions':{let panel=$('#solution-links');panel.hidden=!panel.hidden;b.setAttribute('aria-expanded',String(!panel.hidden));break}case 'copy-prompt':{let q=QUESTION_INDEX.get(session.ids[session.index]);try{await navigator.clipboard.writeText(prompt(q));toast('題目與提問內容已複製，可貼到 ChatGPT。')}catch{$('#modal').innerHTML='<h2>解題問題</h2><textarea>'+e(prompt(q))+'</textarea><button onclick="this.closest(\'dialog\').close()">關閉</button>';$('#modal').showModal();let area=$('#modal textarea');area.focus();area.select()}break}case 'export':download('行政日課-備份-'+new Date().toISOString().slice(0,10)+'.json',{format:'adminDaily.backup.v1',data:DATA});break;case 'schema':download('題庫匯入範例.json',{questions:[{id:'116-adminlaw-mc-1',year:116,subject:'行政法概要',type:'mc',number:1,text:'請替換為官方完整題目',options:['選項 A','選項 B','選項 C','選項 D'],answers:['A'],source:'https://wwwq.moex.gov.tw/'},{id:'116-politics-essay-1',year:116,subject:'政治學概要',type:'essay',number:1,text:'請替換為官方申論題目',source:'https://wwwq.moex.gov.tw/'}]});break;case 'check-updates':window.open('https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y='+new Date().getFullYear(),'_blank','noopener');break}});
document.addEventListener('change',ev=>{let t=ev.target;if(t.dataset.errorReason){updateErrorMeta(t.dataset.errorReason,{reason:t.value});const state=t.closest('.error-editor')?.querySelector('.error-save-state');if(state)state.textContent='已儲存'}if(t.dataset.errorTags){const tags=normalizeTags(t.value);t.value=tags.join('、')}if(t.id==='wrong-reason'){wrongReason=t.value;page=0;render()}if(t.id==='wrong-tag'){wrongTag=t.value;page=0;render()}if(['from','to','count'].includes(t.id)){config[t.id]=+t.value;save();render()}if(t.dataset.weight){config.weights[t.dataset.weight]=Math.max(0,Math.min(100,+t.value||0));save();$('#weights').innerHTML=weightsUI()}if(t.id==='notes-subject'){notesSubject=t.value;page=0;render()}if(t.id==='bankyear'){bankYear=t.value;page=0;render()}if(t.id==='banksub'){bankSub=t.value;page=0;render()}if(t.id==='review'){let id=session.ids[session.index];DATA.records[id]??={attempts:0,right:0};DATA.records[id].review=t.checked;save()}if(t.id==='bankfile')importFile(t.files[0],false);if(t.id==='backupfile')importFile(t.files[0],true)});
document.addEventListener('input',ev=>{let t=ev.target;if(t.dataset.errorTags){updateErrorMeta(t.dataset.errorTags,{tags:t.value});const state=t.closest('.error-editor')?.querySelector('.error-save-state');if(state)state.textContent='已儲存'}if(t.id==='note'){saveNote(session.ids[session.index],t.value)}if(t.dataset.noteEdit){saveNote(t.dataset.noteEdit,t.value);const item=t.closest('.note-entry');item.querySelector('.note-content').textContent=t.value||'尚未填寫';item.querySelector('.note-save-state').textContent='已儲存';const count=$('#notes-total');if(count)count.textContent=noteEntries().length}if(t.id==='notes-search'){notesSearch=t.value;page=0;clearTimeout(window.notesSearchTimer);window.notesSearchTimer=setTimeout(()=>{render();$('#notes-search').focus();$('#notes-search').setSelectionRange(notesSearch.length,notesSearch.length)},350)}if(t.id==='draft'){DATA.drafts[session.ids[session.index]]=t.value;$('#wordcount').textContent=t.value.length+' 字';save()}if(t.id==='search'){search=t.value;page=0;clearTimeout(window.searchTimer);window.searchTimer=setTimeout(()=>{render();$('#search').focus();$('#search').setSelectionRange(search.length,search.length)},350)}});
function decodeBank(d){if(d.format!=='adminDaily.bank.v2')return d;return {papers:d.papers,questions:d.questions.map(q=>{const n={...q};for(const field of ['source','answerSource'])if(typeof n[field]==='number')n[field]=d.sources[n[field]];if(typeof n.context==='number')n.context=d.contexts[n.context];if(n.translation&&typeof n.translation.context==='number')n.translation={...n.translation,context:d.contexts[n.translation.context]};return n})}}
async function init(){load();scheduleDailyQuote();try{const r=await (globalThis.__BANK_REQUEST||fetch('__BANK_URL__'));if(!r||!r.ok)throw Error();const d=decodeBank(await r.json());PAPERS=d.papers;BANK=d.questions;let m=new Map(BANK.map(q=>[q.id,q]));DATA.custom.forEach(q=>m.set(q.id,q));BANK=[...m.values()];applyCurrentSyllabus();save();render()}catch{$('#app').innerHTML='<div class="card" style="margin-top:30px"><h2>題庫暫時無法載入</h2><p>請確認網路後重新整理。</p><button onclick="location.reload()">重新整理</button></div>'}}
init();
